head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환)
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
scwin.makeDataList = function(id, obj) {
	if (scwin.__getObj(id) != undefined) {
		$w.data.remove(id);
	}
	$w.data.create({
		"id": id,
		"type": "dataList",
		"option": {
			"useData": false
		},
		"columnInfo": obj
	});
};
scwin.setColumnID = function(obj) {
	var column = {};
	var columnArr = [];
	var gridHeader = "",
		gridBody = "";
	// json 첫 번째 데이터의 키로 dataList·gridView 컬럼 정의(col1 만 colMerge)
	for (var k in obj[0]) {
		column = {};
		column["id"] = k;
		column["dataType"] = "text";
		columnArr.push(column);
		gridHeader += '<w2:column blockSelect="false" id="' + 'h' + k + '" style="height:20px" inputType="text" width="70" value="' + k + '" useFilter="true"></w2:column>';
		if (k == 'col1') {
			gridBody += '<w2:column blockSelect="false" id="' + k + '" style="height:20px" inputType="text" width="70" colMerge="true"></w2:column>'
		} else {
			gridBody += '<w2:column blockSelect="false" id="' + k + '" style="height:20px" inputType="text" width="70" ></w2:column>'
		}
	}
	scwin.makeDataList("dataList1", columnArr);
	var gridStr = '<w2:gridView xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" dataList="dataList1" scrollByColumn="false" id="gridView1" style="width: 500px;height: 350px;" fixedColumnWithHidden="true" useShiftKey="false" ev:ongroupby="scwin.ongrp" autoFit="allColumn" groupbyZone="true" groupbyFilterBox="true" customFilterBox="true" useFilterList="true" rowNumWidth="" >' +
		'<w2:header id="header1" style="">' +
		'<w2:row id="row1" style="">' +
		gridHeader +
		'</w2:row>' +
		'</w2:header>' +
		'<w2:gBody id="gBody1" style="">' +
		'<w2:row id="row2" style="">' +
		gridBody +
		'</w2:row>' +
		'</w2:gBody>' +
		'</w2:gridView>';
	gridView1.setGridStyle(WebSquare.xml.parse(gridStr, true));
	dataList1.setJSON(obj);
};
scwin.ongrp = function(options) {
	options.groupbyHeader = [];
	options.groupbyFooter = [];
	gridView1.groupby(options);
};
scwin.onpageload = function() {
	window.jsonData1 = [
		{ col0: "0", col1: "test", col2: "test", col3: "test" },
		{ col0: "01", col1: "test", col2: "test", col3: "test" },
		{ col0: "01", col1: "test1", col2: "test", col3: "test" },
		{ col0: "02", col1: "test1", col2: "test", col3: "test" },
		{ col0: "02", col1: "test2", col2: "test", col3: "test" },
		{ col0: "02", col1: "test2", col2: "test", col3: "test" },
		{ col0: "03", col1: "test3", col2: "test", col3: "test" },
		{ col0: "03", col1: "test3", col2: "test", col3: "test" },
		{ col0: "03", col1: "test4", col2: "test", col3: "test" },
		{ col0: "04", col1: "test4", col2: "test", col3: "test" },
		{ col0: "04", col1: "test5", col2: "test", col3: "test" },
		{ col0: "04", col1: "test5", col2: "test", col3: "test" }
	];
};
